import{c as t,Q as a,j as r,m as i}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Quick Start Guide - Hyperliquid Asset Recovery in 5 Minutes","description":"Learn how to check your restricted Hyperliquid address and start asset recovery using the Telegram Bot. A step-by-step 5-minute withdrawal guide.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/en/quick-start"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/quick-start"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/quick-start"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/quick-start"}],["meta",{"name":"keywords","content":"Hyperliquid quick start, recover hyperliquid assets, high risk address check, Hyperliquid withdrawal bypass, Telegram recovery bot"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Quick Start Guide - Hyperliquid Asset Recovery in 5 Minutes"}],["meta",{"property":"og:description","content":"Learn how to check your restricted Hyperliquid address and start asset recovery using the Telegram Bot. A step-by-step 5-minute withdrawal guide."}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/en/quick-start"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Quick Start Guide - Hyperliquid Asset Recovery in 5 Minutes"}],["meta",{"name":"twitter:description","content":"Learn how to check your restricted Hyperliquid address and start asset recovery using the Telegram Bot. A step-by-step 5-minute withdrawal guide."}]]},"headers":[],"relativePath":"en/quick-start.md","filePath":"en/quick-start.md","lastUpdated":null}'),s={name:"en/quick-start.md"};function o(l,e,n,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>This page gives you a 5-minute path to complete your first detection and recovery run.</p><p>Use this workflow if your address can connect in Hyperliquid frontend but a red high-risk warning overlay appears and common operation buttons are typically disabled or restricted.</p><h2 id="_1-open-the-bot" tabindex="-1">1) Open the Bot <a class="header-anchor" href="#_1-open-the-bot" aria-label="Permalink to &quot;1) Open the Bot&quot;">​</a></h2><ul><li>Official entry: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">https://t.me/HyperliquidRecoveryBot</a></li><li>Or search in Telegram: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li>Send <code>/start</code> to initialize your session</li></ul><h2 id="_2-run-address-detection-first" tabindex="-1">2) Run Address Detection First <a class="header-anchor" href="#_2-run-address-detection-first" aria-label="Permalink to &quot;2) Run Address Detection First&quot;">​</a></h2><ol><li>Tap <code>🔍 Address Detection</code> or send <code>/detect</code></li><li>Enter the source address (<code>0x</code> prefix, 42 chars)</li><li>Wait for the bot to scan your spot, perpetual, vault, and staking-related assets</li><li>Review total value, any waiting or locked assets, and what can be handled now</li></ol><h2 id="_3-start-asset-recovery" tabindex="-1">3) Start Asset Recovery <a class="header-anchor" href="#_3-start-asset-recovery" aria-label="Permalink to &quot;3) Start Asset Recovery&quot;">​</a></h2><ol><li>Tap <code>🛠️ Asset Recovery</code> or send <code>/recovery</code></li><li>Enter source address (flagged address)</li><li>Enter private key or mnemonic (used only for signing)</li><li>Confirm plan and fee breakdown, then execute</li></ol><p>Note: if some assets cannot be handled yet, the preview will show that they need to wait instead of making them look immediately available.</p><h2 id="_4-what-you-will-see" tabindex="-1">4) What You Will See <a class="header-anchor" href="#_4-what-you-will-see" aria-label="Permalink to &quot;4) What You Will See&quot;">​</a></h2><ul><li>A guided multi-step progress view</li><li>Step-by-step status updates showing whether each part finished, is waiting, was skipped, or failed</li><li>A result page telling you whether the run is complete, partial, needs another run later, or failed</li><li>A final summary with recovered amount, actual fees, and transaction hashes</li></ul><h2 id="_5-fee-semantics" tabindex="-1">5) Fee Semantics <a class="header-anchor" href="#_5-fee-semantics" aria-label="Permalink to &quot;5) Fee Semantics&quot;">​</a></h2><ul><li><code>Service Fee</code>: 0.5%, minimum 1 USDC</li><li><code>Withdrawal Fees</code>: 2 USDC (two withdrawals)</li><li><code>Total Cost</code>: Service Fee + Withdrawal Fees</li><li><code>You Will Receive</code>: Estimated Recoverable Value - Total Cost</li></ul><p>See <a href="./fee-and-settlement">Fee and Settlement</a> for full examples.</p><h2 id="_6-special-cases" tabindex="-1">6) Special Cases <a class="header-anchor" href="#_6-special-cases" aria-label="Permalink to &quot;6) Special Cases&quot;">​</a></h2><ul><li><strong>Staked assets</strong>: may require waiting windows; bot tells you when to rerun.</li><li><strong>Locked vault assets</strong>: assets that are temporarily unavailable will be marked as waiting and can be retried later.</li><li><strong>Small balances</strong>: some steps may not be generated due to minimum withdrawal limits.</li><li><strong>Arrival latency</strong>: after withdrawal is submitted, funds may arrive in several to more than ten minutes depending on Hyperliquid processing.</li></ul><h2 id="_7-security-checklist" tabindex="-1">7) Security Checklist <a class="header-anchor" href="#_7-security-checklist" aria-label="Permalink to &quot;7) Security Checklist&quot;">​</a></h2><ol><li>Use the official bot only</li><li>Operate on trusted device/network</li><li>Verify the same source address can receive on Arbitrum</li><li>Never screenshot or share credentials</li></ol><h2 id="next-reading" tabindex="-1">Next Reading <a class="header-anchor" href="#next-reading" aria-label="Permalink to &quot;Next Reading&quot;">​</a></h2><ul><li><a href="./asset-recovery">Asset Recovery</a></li><li><a href="./execution-status">Execution Status</a></li><li><a href="./faq">FAQ</a></li></ul>',21)])])}const y=t(s,[["render",o]]);export{p as __pageData,y as default};
